<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Create;

use Throwable;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Create\TemplateAssetCreateAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedCreateAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(TemplateAssetCreateAllowDecision $proposal): TemplateAssetCreateAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedCreateAllow Template asset");
        $span = $this->startSpan("Check IsAuthenticatedCreateAllow Template asset");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if ($userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedCreate');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
